import { Component, OnInit } from '@angular/core';
import { CongestionLevelsService } from '../../services/congestion-levels.service';
import { AccordionModule } from 'ngx-bootstrap/accordion';
import { CommonModule } from '@angular/common';
import { CongestionLevel } from '../../interfaces/congestion-levels.interface';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { take } from 'rxjs';
import { CongestionRuleModalComponent } from './congestion-rule-modal-component/congestion-rule-modal-component';
import { ConfirmDialogComponent } from '../confirm-dialog-component/confirm-dialog-component';

@Component({
  selector: 'app-congestion-levels',
  standalone: true,
  imports: [CommonModule, AccordionModule],
  templateUrl: './congestion-levels.html',
  styleUrl: './congestion-levels.scss'
})
export class CongestionLevels implements OnInit {
  congestionLevels: CongestionLevel[] = [];
  modalRef?: BsModalRef;

  constructor(
    private readonly congestionService: CongestionLevelsService,
    private readonly modalService: BsModalService
  ) {}

  ngOnInit(): void {
    this.getCongestionLevels();
  }

  getCongestionLevels() {
    this.congestionService.getCongestionLevels().pipe(take(1)).subscribe(data => {
      this.congestionLevels = data;
    });
  }

  openAddRuleModal() {
    this.modalRef = this.modalService.show(CongestionRuleModalComponent, {
      initialState: {
        title: 'Add Congestion Rule'
      }
    });
    this.onHiddenModal(this.modalRef);
  }

  openEditRule(rule: any) {
    this.modalRef = this.modalService.show(CongestionRuleModalComponent, {
      initialState: {
        ruleData: rule,
        id: rule.id
      }
    });
    this.onHiddenModal(this.modalRef);
  }

  onHiddenModal(modalRef: BsModalRef) {
    modalRef.onHidden?.subscribe(() => {
      // Refresh table or fetch new data after modal closes
      console.log('Modal closed');
      this.getCongestionLevels();
    });
  }

  confirmDelete(rule: any) {
    this.modalRef = this.modalService.show(ConfirmDialogComponent, {
      initialState: {
        title: 'Delete Rule',
        message: `Are you sure you want to delete the rule "${rule.signalId} - ${rule.description}"?`
      }
    });

    const content = this.modalRef.content as ConfirmDialogComponent;
    content.onClose = (result: boolean) => {
      if (result) {
        this.deleteRule(rule);
      }
    };
  }

  deleteRule(rule: any) {
    console.log('Deleting rule:', rule);
    this.congestionService.deleteCongestionLevel(rule.id).pipe(take(1)).subscribe(() => {
      this.getCongestionLevels();
    });
  }
}

import { Component, Input, OnInit } from '@angular/core';
import { CongestionLevelsService } from '../../../services/congestion-levels.service';
import { FormArray, FormBuilder, FormGroup, Validators, ReactiveFormsModule, ValidatorFn, AbstractControl, ValidationErrors } from '@angular/forms';
import { BsModalRef } from 'ngx-bootstrap/modal';
import { take } from 'rxjs';
import { CongestionLevel } from '../../../interfaces/congestion-levels.interface';
import { CommonModule } from '@angular/common';
import { Signal } from '../../../interfaces/signal-config.interface';
import { SignalConfigService } from '../../../services/signal-config.service';

@Component({
  selector: 'app-congestion-rule-modal-component',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './congestion-rule-modal-component.html',
  styleUrl: './congestion-rule-modal-component.scss'
})
export class CongestionRuleModalComponent implements OnInit {
  @Input() ruleData: any = null;
  @Input() id: number = 0;
  congestionLevels: CongestionLevel[] = [];
  logicOptions: string[] = [];
  fields: string[] = [];
  operators: string[] = [];
  signals: Signal[] = [];
  title?: string = 'Congestion Levels';
  ruleForm!: FormGroup;
  errorInLogic: boolean = false;

  constructor(
    public bsModalRef: BsModalRef,
    private readonly fb: FormBuilder,
    private readonly congestionService: CongestionLevelsService,
    private readonly signalService: SignalConfigService
  ) {}

  ngOnInit(): void {
    this.signalsInfo();
    this.logicOptionsInfo();
    this.fieldsInfo();
    this.operatorsInfo();
    this.ruleForm = this.fb.group({
      description: ['', Validators.required],
      signalId: ['', Validators.required],
      conditions: this.fb.array([]),
      logic: ['NONE', Validators.required],
      enabled: [{ value: true, disabled: false }]
    }, { validators: this.logicValidator() });
    if (this.ruleData) {
      this.loadRuleData(this.ruleData);
    } else {
      this.addCondition();
    }
  }

  get conditions(): FormArray {
    return this.ruleForm.get('conditions') as FormArray;
  }

  get logicError(): boolean {
    return this.ruleForm.hasError('invalidLogic') && (this.ruleForm.get('logic')?.touched ?? false);
  }

  loadRuleData(rule: any) {
    this.ruleForm.patchValue({
      description: rule.description,
      signalId: rule.signalId,
      logic: rule.ruleExpression.logic,
      enabled: rule.enabled
    });

    // Prefill conditions
    rule.ruleExpression.conditions.forEach((cond: any) => this.addCondition(cond));
  }

  signalsInfo() {
    this.signalService.getSignals().pipe(take(1)).subscribe(data => {
      this.signals = data;
    });
  }

  logicOptionsInfo() {
    this.logicOptions = this.congestionService.getLogicOptions();
  }

  fieldsInfo() {
    this.fields = this.congestionService.getFields();
  }

  operatorsInfo() {
    this.operators = this.congestionService.getOperators();
  }

  addCondition(condition: any = null) {
    this.conditions.push(
      this.fb.group({
        field: [condition?.field || '', Validators.required],
        operator: [condition?.operator || '', Validators.required],
        value: [condition?.value || '', Validators.required],
      })
    );
  }

  removeCondition(index: number) {
    this.conditions.removeAt(index);
  }

  submit() {
    if (this.ruleForm?.invalid) {
      this.ruleForm.markAllAsTouched();
      return;
    }
    if (this.ruleForm?.valid) {
      const payload = this.ruleForm.getRawValue();

      const { conditions, logic, ...restOfProperties } = payload;

      const congestionLevelRequest: CongestionLevel = {
          ...restOfProperties,
          ruleExpression: {
              conditions,
              logic
          }
      };

      if (this.id) {
        this.congestionService.updateCongestionLevel(congestionLevelRequest, this.id).pipe(take(1)).subscribe(() => {
          console.log('Congestion level updated successfully');
        });
      } else {
        this.congestionService.setCongestionLevel(congestionLevelRequest).pipe(take(1)).subscribe(() => {
          console.log('Congestion level added successfully');
        });
      }

      this.bsModalRef?.hide();
    }
  }

  logicValidator(): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      const conditions = control.get('conditions') as FormArray;
      const logic = control.get('logic')?.value;

      if (conditions && conditions.length > 1 && logic === 'NONE') {
        return { invalidLogic: true };
      }
      if (conditions && conditions.length <= 1 && logic !== 'NONE') {
        return { invalidLogic: true };
      }
      return null;
    };
  }
}

import { Component, OnInit } from '@angular/core';
import { SignalConfigService } from '../../services/signal-config.service';
import { SignalStatus } from '../../interfaces/signal-config.interface';
import { CommonModule, NgIf, NgClass } from "@angular/common";
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';
import { ManualOverride } from './manual-override/manual-override';
import { HighchartsChartComponent } from 'highcharts-angular';
import { TabDirective, TabsetComponent } from "ngx-bootstrap/tabs";
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-dashboard',
  imports: [CommonModule, HighchartsChartComponent, TabsetComponent, TabDirective, NgIf, FormsModule, NgClass],
  templateUrl: './dashboard.html',
  styleUrl: './dashboard.scss'
})
export class Dashboard implements OnInit {
  signalStatus: SignalStatus[] = [];
  modalRef?: BsModalRef;
  region: string = '';
  regions: string[] = ['Karnataka'];
  showTrafficData: boolean = false;
  errorLoadingTrafficData: boolean = false;
  alertMessage: string = '';
  // Highcharts configurations
  public totalVehiclesChartOptions!: Highcharts.Options;
  public vehicleTypeBreakdownChartOptions!: Highcharts.Options;
  public congestionPieChartOptions!: Highcharts.Options;

  constructor(private readonly signalService: SignalConfigService,
    private readonly modalService: BsModalService
  ) { }

  ngOnInit(): void {
    this.getSignalStatus();
  }

  loadTrafficData() {
    this.signalService.loadTrafficData(this.region).subscribe({
      next: (response) => {
        console.log('Traffic data load initiated successfully:', response);
        // Optionally, you can show a success message to the user here
        this.showTrafficData = true;
        this.alertMessage = response?.message || 'Traffic data load initiated successfully.';
        this.hideAlert();
      },
      error: (error) => {
        console.error('Error loading traffic data:', error);
        this.showTrafficData = true;
        this.errorLoadingTrafficData = true;
        this.alertMessage = error?.error?.message || 'An error occurred while loading traffic data.';
        this.hideAlert();
        // Optionally, you can show an error message to the user here
      }
    });
  }

  hideAlert() {
    setTimeout(() => {
      this.showTrafficData = false;
      this.errorLoadingTrafficData = false;
    }, 5000);
  }

  getSignalStatus() {
    this.signalService.getSignalStatus().subscribe((data) => {
      this.signalStatus = data;
      this.createTotalVehiclesChart();
      this.createVehicleTypeBreakdownChart();
      this.createCongestionPieChart();
    });
  }

  editManualOverride(s: SignalStatus) {
    console.log('Editing manual override for signal:', s);
    this.modalRef = this.modalService.show(ManualOverride, {
      initialState: {
        signalData: s
      }
    });
    this.onHiddenModal(this.modalRef);
  }

  onHiddenModal(modalRef: BsModalRef) {
    modalRef.onHidden?.subscribe(() => {
      console.log('Modal closed');
      this.getSignalStatus();
    });
  }

  /**
   * 1. Total Vehicle Count by Signal (Column Chart)
   */
  private createTotalVehiclesChart(): void {
    const categories = this.signalStatus.map(data => data.signalLocation);
    const dataSeries = this.signalStatus.map(data => ({
      name: data.signalLocation,
      y: data.lmvCount + data.hmvCount + data.htvCount + data.mcwgCount + data.mgvCount,
      // Highlight congested signals in Red
      color: data.congested ? '#EF5350' : '#66BB6A'
    }));

    this.totalVehiclesChartOptions = {
      chart: { type: 'column' },
      title: { text: 'Total Vehicle Count by Location' },
      xAxis: { categories: categories, title: { text: 'Traffic Signal Location' } },
      yAxis: { min: 0, title: { text: 'Total Vehicle Count' } },
      tooltip: { headerFormat: '<b>{point.key}</b><br/>', pointFormat: 'Total Vehicles: <b>{point.y}</b>' },
      legend: { enabled: false },
      series: [{
        name: 'Total Vehicles',
        data: dataSeries,
        type: 'column'
      }]
    };
  }

  /**
   * 2. Vehicle Type Breakdown (Stacked Column Chart)
   */
  private createVehicleTypeBreakdownChart(): void {
    const categories = this.signalStatus.map(data => data.signalLocation);

    // Create series for each vehicle type
    const lmvData = this.signalStatus.map(d => d.lmvCount);
    const mcwgData = this.signalStatus.map(d => d.mcwgCount);
    const mgvData = this.signalStatus.map(d => d.mgvCount);
    const hmvData = this.signalStatus.map(d => d.hmvCount);
    const htvData = this.signalStatus.map(d => d.htvCount);

    this.vehicleTypeBreakdownChartOptions = {
      chart: { type: 'column' },
      title: { text: 'Vehicle Type Breakdown Across Locations' },
      xAxis: { categories: categories },
      yAxis: {
        min: 0,
        title: { text: 'Vehicle Count' },
        stackLabels: { enabled: true, format: '{total}' } // Show total on stack
      },
      legend: { reversed: true },
      plotOptions: {
        series: {
          stacking: 'normal', // Stacks the columns
          dataLabels: { enabled: false }
        }
      },
      series: [
        { name: 'HTV (Heavy Transport)', data: htvData, type: 'column' },
        { name: 'HMV (Heavy Motor)', data: hmvData, type: 'column' },
        { name: 'MGV (Medium Goods)', data: mgvData, type: 'column' },
        { name: 'MCWG (Motor Cycle)', data: mcwgData, type: 'column' },
        { name: 'LMV (Light Motor)', data: lmvData, type: 'column' }
      ]
    };
  }


  /**
   * 3. Congestion Status Distribution (Pie Chart)
   */
  private createCongestionPieChart(): void {
    const congestedCount = this.signalStatus.filter(d => d.congested).length;
    const notCongestedCount = this.signalStatus.filter(d => !d.congested).length;

    this.congestionPieChartOptions = {
      chart: { type: 'pie' },
      title: { text: 'Congestion Status Distribution' },
      tooltip: { pointFormat: '<b>{point.y} signals ({point.percentage:.1f}%)</b>' },
      plotOptions: {
        pie: {
          allowPointSelect: true,
          cursor: 'pointer',
          dataLabels: { enabled: true, format: '<b>{point.name}</b>: {point.percentage:.1f} %' }
        }
      },
      series: [{
        name: 'Signals',
        data: [{
          name: 'Congested',
          y: congestedCount,
          color: '#EF5350' // Red
        }, {
          name: 'Not Congested',
          y: notCongestedCount,
          color: '#66BB6A', // Green
          sliced: true,
          selected: true
        }],
        type: 'pie'
      }]
    };
  }
}

